cli.cjs.content:
const { formatStatus } = require('./format.cjs');
const [status, title, ...extra] = process.argv.slice(2);
if (status === undefined || title === undefined || extra.length) {
  process.stderr.write('usage: node cli.cjs STATUS TITLE\n');
  process.exitCode = 2;
} else {
  process.stdout.write(formatStatus(status, title) + '\n');
}

format.cjs.content:
function formatStatus(status, title) {
  if (status === 'queued') {
    return '[WAIT] ' + title;
  }
  if (status === 'active') {
    return '[RUN] ' + title;
  }
  if (status === 'paused') {
    return '[HOLD] ' + title;
  }
  if (status === 'done') {
    return '[OK] ' + title;
  }
  if (status === 'failed') {
    return '[FAIL] ' + title;
  }
  if (status === 'cancelled') {
    return '[STOP] ' + title;
  }
  return '[?] ' + title;
}
module.exports = { formatStatus };

format.test.cjs.content:
const test = require('node:test');
const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const path = require('node:path');
const { formatStatus } = require('./format.cjs');
const formatRows = require('./consumer.cjs');

test('formats each exact status without appending a newline', () => {
  assert.equal(formatStatus('queued', 'Task'), '[WAIT] Task');
  assert.equal(formatStatus('active', 'Task'), '[RUN] Task');
  assert.equal(formatStatus('paused', 'Task'), '[HOLD] Task');
  assert.equal(formatStatus('done', 'Task'), '[OK] Task');
  assert.equal(formatStatus('failed', 'Task'), '[FAIL] Task');
  assert.equal(formatStatus('cancelled', 'Task'), '[STOP] Task');
});

test('unknown, differently cased, and prototype-property statuses use fallback', () => {
  for (const status of ['unknown', 'Queued', 'QUEUED', ' queued', 'queued ', '',
    '__proto__', 'constructor', 'toString', 'hasOwnProperty']) {
    assert.equal(formatStatus(status, 'Task'), '[?] Task');
  }
});

test('status comparison never coerces non-string values', () => {
  const hostile = new Proxy({}, { get() { throw new Error('status was inspected'); } });
  for (const status of [undefined, null, 0, NaN, false, 1n, Symbol('queued'),
    new String('queued'), ['queued'], hostile]) {
    assert.equal(formatStatus(status, 'Task'), '[?] Task');
  }
});

test('keeps title whitespace, Unicode, and primitive coercion', () => {
  assert.equal(formatStatus('done', ''), '[OK] ');
  assert.equal(formatStatus('done', '  café\n雪\t'), '[OK]   café\n雪\t');
  assert.equal(formatStatus('done', undefined), '[OK] undefined');
  assert.equal(formatStatus('done', null), '[OK] null');
  assert.equal(formatStatus('done', 12), '[OK] 12');
  assert.equal(formatStatus('done', false), '[OK] false');
  assert.equal(formatStatus('done', 12n), '[OK] 12');
  assert.equal(formatStatus(), '[?] undefined');
});

test('title conversion uses the default hint exactly once', () => {
  const hints = [];
  const title = { [Symbol.toPrimitive](hint) { hints.push(hint); return 'converted'; } };
  assert.equal(formatStatus('active', title), '[RUN] converted');
  assert.deepEqual(hints, ['default']);
  assert.equal(formatStatus('done', { valueOf() { return 7; } }), '[OK] 7');
});

test('title conversion errors propagate on known and fallback paths', () => {
  const failure = new Error('title failure');
  for (const status of ['queued', 'active', 'paused', 'done', 'failed', 'cancelled', '?']) {
    assert.throws(() => formatStatus(status, Symbol('title')), TypeError);
    assert.throws(() => formatStatus(status, {
      [Symbol.toPrimitive]() { throw failure; }
    }), error => error === failure);
  }
});

test('consumer preserves row order, holes, and errors', () => {
  assert.deepEqual(formatRows([{ status: 'done', title: 'One' }, {},
    { status: 'active', title: 'Two' }]), ['[OK] One', '[?] undefined', '[RUN] Two']);
  const sparse = [];
  sparse[1] = { status: 'queued', title: 'Later' };
  const result = formatRows(sparse);
  assert.equal(result.length, 2);
  assert.equal(0 in result, false);
  assert.equal(result[1], '[WAIT] Later');
  assert.throws(() => formatRows([null]), TypeError);
});

test('CLI preserves output bytes and accepts empty arguments', () => {
  for (const [args, stdout] of [
    [['queued', 'Task'], '[WAIT] Task\n'],
    [['active', 'Task'], '[RUN] Task\n'],
    [['paused', 'Task'], '[HOLD] Task\n'],
    [['done', 'Task'], '[OK] Task\n'],
    [['failed', 'Task'], '[FAIL] Task\n'],
    [['cancelled', 'Task'], '[STOP] Task\n'],
    [['Queued', 'Task'], '[?] Task\n'],
    [['__proto__', 'Task'], '[?] Task\n'],
    [['', ''], '[?] \n'],
    [['done', 'café\n雪'], '[OK] café\n雪\n']
  ]) {
    const result = spawnSync(process.execPath, [path.join(__dirname, 'cli.cjs'), ...args],
      { encoding: 'utf8', timeout: 5000 });
    assert.equal(result.error, undefined);
    assert.equal(result.status, 0);
    assert.equal(result.stdout, stdout);
    assert.equal(result.stderr, '');
  }
});

test('CLI rejects missing and extra arguments with exact usage on stderr', () => {
  for (const args of [[], ['done'], ['done', 'Task', 'extra'], ['done', '', '']]) {
    const result = spawnSync(process.execPath, [path.join(__dirname, 'cli.cjs'), ...args],
      { encoding: 'utf8', timeout: 5000 });
    assert.equal(result.error, undefined);
    assert.equal(result.status, 2);
    assert.equal(result.stdout, '');
    assert.equal(result.stderr, 'usage: node cli.cjs STATUS TITLE\n');
  }
});

