const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const path = require('node:path');
const before = require('./baseline/format.cjs').formatStatus;
const after = require('../app/format.cjs').formatStatus;
const statuses = ['queued', 'active', 'paused', 'done', 'failed', 'cancelled',
  'unknown', '', 'Queued', ' queued', 'queued ', '__proto__', 'constructor',
  'toString', 'hasOwnProperty', undefined, null, 0, NaN, false, 1n,
  Symbol('queued'), new String('queued'), ['queued'],
  new Proxy({}, { get() { throw new Error('status inspected'); } })];
const titleFactories = [() => 'Task', () => '', () => '  café\n雪\t',
  () => undefined, () => null, () => 0, () => -0, () => NaN, () => false,
  () => 12n, () => Symbol('title'), () => ({}), () => ['a', 'b'],
  () => Object.create(null), () => ({ valueOf() { return 7; } }),
  () => ({ [Symbol.toPrimitive](hint) { return hint; } }),
  () => ({ [Symbol.toPrimitive]() { throw new Error('conversion failed'); } })];
function outcome(format, status, makeTitle) {
  try { return { value: format(status, makeTitle()) }; }
  catch (error) { return { error: error.name, message: error.message }; }
}
let functionCases = 0;
for (const status of statuses) {
  for (const makeTitle of titleFactories) {
    assert.deepEqual(outcome(after, status, makeTitle), outcome(before, status, makeTitle));
    functionCases++;
  }
}
const cliArgs = statuses.filter(status => typeof status === 'string')
  .flatMap(status => [[status, 'Task'], [status, ''], [status, '  café\n雪\t']]);
cliArgs.push([], ['done'], ['done', 'Task', 'extra'], ['done', '', '']);
function cli(directory, args) {
  const result = spawnSync(process.execPath, [path.join(__dirname, directory, 'cli.cjs'), ...args],
    { timeout: 5000, env: { ...process.env, NODE_OPTIONS: '', LANG: 'C.UTF-8' } });
  if (result.error) throw result.error;
  return { status: result.status, signal: result.signal,
    stdout: result.stdout.toString('base64'), stderr: result.stderr.toString('base64') };
}
for (const args of cliArgs) assert.deepEqual(cli('../app', args), cli('baseline', args));
