from pathlib import Path
import subprocess,json,hashlib,tempfile,sys
root=Path('/tmp/jstack-refactoring-20261016');two='--two-seat' in sys.argv;app=root/('two-seat-app' if two else 'app');out=root/('two-seat-parent' if two else 'parent');out.mkdir(exist_ok=True)
def run(args,cwd):
 p=subprocess.run(args,cwd=cwd,text=True,capture_output=True);return {'argv':args,'cwd':str(cwd),'exit':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()
base=subprocess.check_output(['git','rev-list','--max-parents=0','HEAD'],cwd=app,text=True).strip()
original=out/'baseline';original.mkdir(exist_ok=True)
for name in ['format.cjs','cli.cjs','consumer.cjs','package.json','README.md']:
 (original/name).write_bytes(subprocess.check_output(['git','show',base+':'+name],cwd=app))
statuses=['queued','active','paused','done','failed','cancelled','unknown','','DONE','__proto__','constructor','toString']
titles=['write report','','  spaced  ','café 🐈','line\nbreak','--flag','[OK] title']
cases=[[s,t] for s in statuses for t in titles]+[[],['done'],['done','title','extra']]
def collect(target):return [dict(args=c,**run(['node','cli.cjs',*c],target)) for c in cases]
if 'baseline' in sys.argv:
 rows=collect(original);(out/'baseline.json').write_text(json.dumps({'base':base,'sourceHash':digest(original/'format.cjs'),'cases':rows},indent=2)+'\n');print(json.dumps({'base':base,'cases':len(rows)}));raise SystemExit
before=json.loads((out/'baseline.json').read_text());rows=collect(app)
compare=lambda x,y:all(x[k]==y[k] for k in ['exit','stdout','stderr'])
fail=[{'args':a['args'],'before':a,'after':b} for a,b in zip(before['cases'],rows) if not compare(a,b)]
control=out/'negative-control';control.mkdir(exist_ok=True)
(control/'cli.cjs').write_bytes((app/'cli.cjs').read_bytes());(control/'format.cjs').write_text((app/'format.cjs').read_text().replace('WAIT','WAITING'))
negative=collect(control);detected=[r['args'] for a,r in zip(before['cases'],negative) if not compare(a,r)]
api_code="""const assert=require('node:assert/strict');
const a=require(process.argv[1]);const b=require(process.argv[2]);assert.deepEqual(Object.keys(a),Object.keys(b));
const statuses=['queued','active','paused','done','failed','cancelled','__proto__','constructor',null,undefined,1,true,new String('queued'),['queued'],{toString(){return 'queued'}},Symbol('queued'),{}];
const titles=['','a',null,undefined,1,{toString(){return 'title'}},Symbol('title')];
const result=(f,s,t)=>{try{return {value:f(s,t)}}catch(e){return {error:e.name,message:e.message}}};
let n=0;for(const s of statuses)for(const t of titles){assert.deepEqual(result(a.formatStatus,s,t),result(b.formatStatus,s,t));n++}
console.log(n+' imported API equivalence cases passed');"""
exports=run(['node','-e',api_code,str(original/'format.cjs'),str(app/'format.cjs')],app)
test=run(['node','--test'],app)
unchanged={name:digest(original/name)==digest(app/name) for name in ['cli.cjs','consumer.cjs','package.json','README.md']}
result={'baseline':base,'current':subprocess.check_output(['git','rev-parse','HEAD'],cwd=app,text=True).strip(),'publicCases':len(rows),'failures':fail,'cases':rows,'negativeControlDetected':detected,'apiEquivalence':exports,'tests':test,'unchangedFiles':unchanged,'status':run(['git','status','--short'],app)}
(out/'verification.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps({k:v for k,v in result.items() if k not in ['cases','tests','apiEquivalence']},indent=2))
assert not fail and detected and exports['exit']==test['exit']==0 and all(unchanged.values())

jstack-refactoring-history.py.content:
from pathlib import Path
import tempfile,subprocess,json,hashlib,sys
root=Path('/tmp/jstack-refactoring-20261016');two='--two-seat' in sys.argv;app=root/('two-seat-app' if two else 'app');out=root/('two-seat-parent' if two else 'parent')
baseline=json.loads((out/'baseline.json').read_text());base=baseline['base']
def git(*args):return subprocess.check_output(['git',*args],cwd=app,text=True)
commits=git('rev-list','--reverse',base+'..HEAD').splitlines();records=[]
for commit in commits:
 with tempfile.TemporaryDirectory(prefix='jstack-refactor-replay-')as temp:
  temp=Path(temp)
  for name in git('ls-tree','-r','--name-only',commit).splitlines():
   p=temp/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(subprocess.check_output(['git','show',commit+':'+name],cwd=app))
  t=subprocess.run(['node','--test'],cwd=temp,text=True,capture_output=True);fail=[];proof=[]
  for old in baseline['cases']:
   p=subprocess.run(['node','cli.cjs',*old['args']],cwd=temp,text=True,capture_output=True);actual={'exit':p.returncode,'stdout':p.stdout,'stderr':p.stderr};proof.append(actual)
   if any(actual[k]!=old[k]for k in actual):fail.append({'args':old['args'],'actual':actual,'expected':old})
  records.append({'commit':commit,'subject':git('show','-s','--format=%s',commit).strip(),'test':{'argv':['node','--test'],'exit':t.returncode,'stdout':t.stdout,'stderr':t.stderr},'publicCases':len(proof),'failures':fail,'resultsSHA256':hashlib.sha256(json.dumps(proof,sort_keys=True).encode()).hexdigest()})
(out/'history-verification.json').write_text(json.dumps(records,indent=2)+'\n')
print(json.dumps([{'commit':r['commit'],'subject':r['subject'],'testExit':r['test']['exit'],'cases':r['publicCases'],'failures':len(r['failures'])}for r in records],indent=2))
assert all(r['test']['exit']==0 and not r['failures']for r in records)
if not records:print('No local delivery commits exist; history replay is not applicable. Uncommitted delivery requires separate final-artifact verification.')

