from pathlib import Path
import json,hashlib,subprocess,sys
root=Path('/home/ubuntu/Dev/skills');scratch=Path('/tmp/jstack-refactoring-20261016');out=root/'research/jstack/evaluations/refactoring';two='--two-seat' in sys.argv;app=scratch/('two-seat-app' if two else 'app');case='two-seat' if two else 'one-seat'
def sha(b):return hashlib.sha256(b).hexdigest()
def git(*args):return subprocess.check_output(['git',*args],cwd=app,text=True)
artifacts={};indexed={}
large_read_dumps={'two-seat-evidence/judge/02.stdout','two-seat-evidence/interrogate-b/00.stdout','two-seat-evidence/how/08-read-audit.stdout','two-seat-evidence/initial-read.txt','two-seat-evidence/design-b/01-instructions.stdout','two-seat-evidence/how/01-instructions.stdout','two-seat-evidence/design-b/03-source.stdout','two-seat-evidence/how/02-contracts.stdout','two-seat-evidence/design-b/04-principles.stdout'}
for p in sorted((scratch/('two-seat-evidence' if two else 'evidence')).rglob('*')):
 if not p.is_file() or '__pycache__' in str(p):continue
 rel=str(p.relative_to(scratch));data=p.read_bytes();record={'sha256':sha(data),'bytes':len(data)}
 # Raw source-reading dumps repeat immutable packaged files; preserve their hashes locally and archive focused runtime artifacts.
 source_read=('read' in p.name and p.name.endswith('.json') and len(data)>10000 and 'sha256' not in p.name and 'hash' not in p.name)
 if p.name.startswith('catalog') or source_read or rel in large_read_dumps:
  record['retention']='Full bytes remain at scratch path; archived by hash to avoid duplicating catalogs/source reads.';indexed[rel]=record
 else:
  if p.name=='commands.jsonl':
   records=[json.loads(line) for line in data.decode().splitlines()]
   for i,row in enumerate(records):
    cmd=row.get('argv',row.get('command',[]));stdout=row.get('stdout','');code=row.get('exit',row.get('exit_status'))
    readonly=bool(cmd and cmd[0]=='cat') or (rel=='two-seat-evidence/commands.jsonl' and i in [2,3,6])
    if readonly and code==0 and len(stdout)>8000:
     row['stdoutIndexed']={'sha256':sha(stdout.encode()),'bytes':len(stdout.encode()),'retention':'Successful source/document read; full stdout remains in original scratch command log. Sources and read hashes retained separately.'};del row['stdout']
   record['structuredCommands']=records
  else:record['content']=data.decode()
  artifacts[rel]=record
scripts={p.name:{'sha256':sha(p.read_bytes()),'content':p.read_text()}for p in [Path('/tmp/jstack-refactoring-verify.py'),Path('/tmp/jstack-refactoring-compare.py'),Path('/tmp/jstack-refactoring-history.py'),Path('/tmp/jstack-refactoring-slices.py'),Path('/tmp/jstack-refactoring-archive.py')]}
files={p:{'sha256':sha((app/p).read_bytes()),'content':(app/p).read_text()}for p in sorted(set(git('ls-files').splitlines()+git('ls-files','--others','--exclude-standard').splitlines()))}
base=git('rev-list','--max-parents=0','HEAD').strip()
r={'scratch':str(scratch),'base':base,'finalHead':git('rev-parse','HEAD').strip(),'history':git('log','--reverse','--format=fuller','--stat'),'diff':git('diff',base),'finalFiles':files,'status':git('status','--short'),'rawArtifacts':artifacts,'indexedSourceReadsAndCatalogs':indexed,'scripts':scripts,'limits':'Artifact archive is not a full transcript. Large successful source-reading outputs and full capability catalogs are indexed by hash, not embedded; structured command records retain their argv, stderr and status. Raw runtime outputs and evaluator failures are retained where captured.'}
(out/(case+'-evaluation.json')).write_text(json.dumps(r,indent=2)+'\n')
for name in ['baseline.json','verification.json','history-verification.json','slice-verification.json']:
 p=scratch/('two-seat-parent' if two else 'parent')/name
 if p.exists():(out/(case+'-parent-'+name)).write_bytes(p.read_bytes())
print(json.dumps({'rawArtifacts':len(artifacts),'indexed':len(indexed),'bytes':(out/(case+'-evaluation.json')).stat().st_size,'head':r['finalHead']}))
